import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Screened BOSS-PC hybrid:
    1) obtain an order-search CPDAG proposal (BOSS/GRaSP fallback),
    2) add a high-recall shrinkage-screened skeleton (and PC when affordable),
    3) prune by restricted Fisher-Z tests with edge-adaptive cutoffs,
    4) orient using baseline directional priors, conservative collider tests,
       and Meek closure.
    """
    import math
    from itertools import combinations
    from causallearn.graph.Endpoint import Endpoint

    n, p = X.shape
    nodes = [GraphNode(f"X{i + 1}") for i in range(p)]
    TAIL, ARROW = Endpoint.TAIL.value, Endpoint.ARROW.value

    def _to_mat(G):
        try:
            M = np.array(G.graph, dtype=int, copy=True)
        except Exception:
            M = np.zeros((p, p), dtype=int)
        if M.shape != (p, p):
            M = np.zeros((p, p), dtype=int)
        np.fill_diagonal(M, 0)
        return M

    def _adj_of(M):
        A = (M != 0) | (M.T != 0)
        np.fill_diagonal(A, False)
        return A

    def _is_dir(M, i, j):
        return M[i, j] == TAIL and M[j, i] == ARROW

    def _run_boss_like():
        for module in ("bench.boss", "bench.grasp"):
            try:
                mod = __import__(module, fromlist=["run_causal_discovery"])
                G = mod.run_causal_discovery(X)
                return G.G if hasattr(G, "G") else G
            except Exception:
                pass
        return GeneralGraph(nodes)

    def _run_pc(alpha):
        try:
            from causallearn.search.ConstraintBased.PC import pc

            try:
                out = pc(
                    X,
                    alpha=alpha,
                    indep_test="fisherz",
                    stable=True,
                    uc_rule=0,
                    uc_priority=2,
                    show_progress=False,
                )
            except TypeError:
                out = pc(X, alpha=alpha, indep_test="fisherz", stable=True, uc_rule=0, uc_priority=2)
            return out.G if hasattr(out, "G") else out
        except Exception:
            try:
                from bench.pc import run_causal_discovery as pc_run

                return pc_run(X)
            except Exception:
                return GeneralGraph(nodes)

    ratio = n / max(p, 1)
    use_pc = p <= 20 or ratio >= 30
    alpha_pc = 0.12 if ratio < 20 else (0.10 if ratio < 35 else 0.07)

    M_b = _to_mat(_run_boss_like())
    M_p = _to_mat(_run_pc(alpha_pc)) if use_pc else np.zeros((p, p), dtype=int)
    A_b, A_p = _adj_of(M_b), _adj_of(M_p)

    Z = X.astype(float) - X.mean(axis=0, keepdims=True)
    sd = Z.std(axis=0, ddof=1, keepdims=True)
    sd[sd < 1e-8] = 1.0
    Z = Z / sd
    R = (Z.T @ Z) / max(n - 1, 1)
    R = np.clip((R + R.T) / 2.0, -1.0, 1.0)
    np.fill_diagonal(R, 1.0)
    lam = float(min(0.18, max(0.02, p / float(max(n + p, 1)))))
    R = (1.0 - lam) * R + lam * np.eye(p)

    P = np.linalg.pinv(R)
    d = np.sqrt(np.maximum(np.diag(P), 1e-12))
    F = -P / np.outer(d, d)
    F = np.clip((F + F.T) / 2.0, -0.999999, 0.999999)
    np.fill_diagonal(F, 0.0)

    score = 0.67 * np.abs(R) + 0.33 * np.abs(F)
    np.fill_diagonal(score, -1.0)
    top_m = min(p - 1, 5 if p <= 10 else (7 if p <= 20 else 10))
    A_scr = np.zeros((p, p), dtype=bool)
    if top_m > 0:
        for i in range(p):
            idx = np.argpartition(score[i], -top_m)[-top_m:]
            A_scr[i, idx] = True
    A_scr = A_scr | A_scr.T
    np.fill_diagonal(A_scr, False)

    r_thr = float(min(0.35, 1.35 * math.sqrt(max(math.log(max(p, 2) + 1.0) / max(n - 1, 1), 1e-12))))
    f_thr = 0.045 if p <= 20 else 0.055
    A_add = A_scr & ((np.abs(R) > r_thr) | (np.abs(F) > f_thr))
    cand = A_b | A_p | A_add
    np.fill_diagonal(cand, False)

    support = 3 * A_b.astype(int) + 2 * A_p.astype(int) + A_add.astype(int) + (np.abs(F) > (f_thr + 0.02)).astype(int)

    p_cache = {}

    def _fisher_p(i, j, S):
        a, b = (i, j) if i < j else (j, i)
        S = tuple(sorted(int(s) for s in S))
        key = (a, b, S)
        if key not in p_cache:
            idx = [a, b] + list(S)
            M = np.linalg.pinv(R[np.ix_(idx, idx)])
            denom = max(float(M[0, 0] * M[1, 1]), 1e-12)
            rho = float(np.clip(-M[0, 1] / math.sqrt(denom), -0.999999, 0.999999))
            z = abs(float(np.arctanh(rho))) * math.sqrt(max(n - len(S) - 3, 1))
            p_cache[key] = float(math.erfc(z / math.sqrt(2.0)))
        return p_cache[key]

    max_k = 3 if p <= 20 else 2
    pool_cap = 8 if p <= 20 else 6

    def _pool(i, j, adj_ref, forbid=()):
        forbid = set(forbid)
        base = [
            k
            for k in range(p)
            if k not in forbid
            and k not in (i, j)
            and (adj_ref[i, k] or adj_ref[j, k] or A_b[i, k] or A_b[j, k] or A_p[i, k] or A_p[j, k] or A_add[i, k] or A_add[j, k])
        ]

        def _rank(k):
            return (support[i, k] + support[j, k], score[i, k] + score[j, k])

        base = sorted(set(base), key=_rank, reverse=True)
        return base[: max(pool_cap, max_k + 1)]

    def _edge_alpha(i, j):
        a = 0.022
        if A_b[i, j]:
            a -= 0.008
        if A_p[i, j]:
            a -= 0.005
        if A_add[i, j]:
            a -= 0.002
        if abs(F[i, j]) > (f_thr + 0.02):
            a -= 0.002
        return float(min(0.024, max(0.003, a)))

    adj = cand.copy()
    sepsets = {}
    for ell in range(max_k + 1):
        snap = adj.copy()
        edges = [(i, j) for i in range(p) for j in range(i + 1, p) if snap[i, j]]
        for i, j in edges:
            pool = _pool(i, j, snap)
            if len(pool) < ell:
                continue
            best = None
            cutoff = _edge_alpha(i, j)
            for S in combinations(pool, ell):
                pv = _fisher_p(i, j, S)
                if pv > cutoff and (best is None or pv > best[0]):
                    best = (pv, S)
            if best is not None:
                adj[i, j] = adj[j, i] = False
                sepsets[(i, j)] = tuple(best[1])

    sep_cache = {}

    def _find_sep(i, j, include=(), exclude=()):
        a, b = (i, j) if i < j else (j, i)
        include = tuple(sorted(int(x) for x in include if x not in (a, b)))
        exclude = tuple(sorted(int(x) for x in exclude if x not in (a, b)))
        key = (a, b, include, exclude)
        if key in sep_cache:
            return sep_cache[key]
        S0 = sepsets.get((a, b))
        if S0 is not None and all(x in S0 for x in include) and all(x not in S0 for x in exclude):
            sep_cache[key] = S0
            return S0
        if len(include) > max_k:
            sep_cache[key] = None
            return None
        forbid = set(include) | set(exclude)
        pool = [k for k in _pool(a, b, cand, forbid=forbid) if k not in forbid]
        cutoff = 0.018
        base = tuple(sorted(include))
        for ell in range(len(base), max_k + 1):
            rem = ell - len(base)
            if rem < 0 or len(pool) < rem:
                continue
            best = None
            for extra in combinations(pool, rem):
                S = tuple(sorted(base + extra))
                pv = _fisher_p(a, b, S)
                if pv > cutoff and (best is None or pv > best[0]):
                    best = (pv, S)
            if best is not None:
                sep_cache[key] = tuple(best[1])
                return sep_cache[key]
        sep_cache[key] = None
        return None

    dirn = np.zeros((p, p), dtype=bool)

    def _undir(i, j):
        return adj[i, j] and not dirn[i, j] and not dirn[j, i]

    def _orient(i, j):
        if not adj[i, j] or dirn[i, j] or dirn[j, i]:
            return False
        dirn[i, j] = True
        dirn[j, i] = False
        return True

    for i in range(p):
        for j in range(i + 1, p):
            if not adj[i, j]:
                continue
            if _is_dir(M_b, i, j) and not _is_dir(M_p, j, i):
                _orient(i, j)
            elif _is_dir(M_b, j, i) and not _is_dir(M_p, i, j):
                _orient(j, i)
            elif _is_dir(M_p, i, j) and _is_dir(M_b, i, j):
                _orient(i, j)
            elif _is_dir(M_p, j, i) and _is_dir(M_b, j, i):
                _orient(j, i)

    for k in range(p):
        nbrs = [i for i in range(p) if adj[k, i]]
        for a in range(len(nbrs)):
            i = nbrs[a]
            for j in nbrs[a + 1 :]:
                if adj[i, j]:
                    continue
                sep_without = _find_sep(i, j, exclude=(k,))
                sep_with = _find_sep(i, j, include=(k,))
                prior = (_is_dir(M_b, i, k) and _is_dir(M_b, j, k)) or (_is_dir(M_p, i, k) and _is_dir(M_p, j, k))
                if (sep_without is not None and sep_with is None) or prior:
                    _orient(i, k)
                    _orient(j, k)

    def _reachability():
        reach = dirn.copy()
        for m in range(p):
            reach = reach | (reach[:, [m]] & reach[[m], :])
        np.fill_diagonal(reach, False)
        return reach

    changed = True
    while changed:
        changed = False
        reach = _reachability()
        todo = []
        for i in range(p):
            for j in range(i + 1, p):
                if not _undir(i, j):
                    continue
                if any(dirn[k, i] and not adj[k, j] for k in range(p) if k not in (i, j)):
                    todo.append((i, j))
                    continue
                if any(dirn[k, j] and not adj[k, i] for k in range(p) if k not in (i, j)):
                    todo.append((j, i))
                    continue
                if any(dirn[i, k] and dirn[k, j] for k in range(p) if k not in (i, j)):
                    todo.append((i, j))
                    continue
                if any(dirn[j, k] and dirn[k, i] for k in range(p) if k not in (i, j)):
                    todo.append((j, i))
                    continue
                pa_j = [k for k in range(p) if k not in (i, j) and dirn[k, j] and _undir(i, k)]
                if any(not adj[a, b] for x, a in enumerate(pa_j) for b in pa_j[x + 1 :]):
                    todo.append((i, j))
                    continue
                pa_i = [k for k in range(p) if k not in (i, j) and dirn[k, i] and _undir(j, k)]
                if any(not adj[a, b] for x, a in enumerate(pa_i) for b in pa_i[x + 1 :]):
                    todo.append((j, i))
                    continue
                if reach[i, j] and not reach[j, i]:
                    todo.append((i, j))
                    continue
                if reach[j, i] and not reach[i, j]:
                    todo.append((j, i))
                    continue
        for a, b in todo:
            changed = _orient(a, b) or changed

    M = np.zeros((p, p), dtype=int)
    for i in range(p):
        for j in range(i + 1, p):
            if not adj[i, j]:
                continue
            if dirn[i, j]:
                M[i, j], M[j, i] = TAIL, ARROW
            elif dirn[j, i]:
                M[i, j], M[j, i] = ARROW, TAIL
            else:
                M[i, j] = M[j, i] = TAIL

    G = GeneralGraph(nodes)
    G.graph = M
    return G
